-- 0047  AmitTransform's two /api/fix operations.
--
-- AmitTransform is one of the thirteen APIs the client designated on 6 October
-- 2026. Migration 0040 added its conversion operation (POST /api/convert) from
-- an OpenAPI document the group wrote from the provider's source code. That
-- document also describes two more operations of the same service, which were
-- not added then:
--
--   POST /api/fix/analyse   reports the UBL elements found and missing in an
--                           invoice, and the field names the next call accepts
--   POST /api/fix/apply     writes given values into the invoice, converts it
--                           and returns the updated JSON and the UBL 2.1 XML
--
-- On 13 October 2026 the client pointed the group to the provider's repository
-- (https://github.com/iamAmiK/invoice-conversion-api). The group called both
-- operations on the deployed service that day, with the invoice data of its
-- Upbrains call of 12 October: both returned status 200 with the bodies the
-- document describes, a buyer reference given to /api/fix/apply appeared in
-- the returned XML, and a call without fixes returned status 400 with the
-- documented error body. The document gained a description for each of the
-- two operations (frontend/public/specs/amittransform-openapi.json,
-- sha256 8698d2470a6c54830d53e3e9242bc11c7e8df94f24c3b7e4041a42066f137d07).
--
-- The rows were built with the importer's own code -- detect, parseOpenApi3,
-- toApiRow, extractDocumentSchemas, toSchemaRows, toFieldRows -- as in 0040.
--
-- Set by hand: the readable names; the company name, to match the record of
-- 0040; and the category of /api/fix/analyse. The importer calls that one
-- Communication (Receive). It prepares a conversion and tests the invoice
-- against no standard, so it is stored as a Transformation like the other two
-- and not as a Validation.
--
-- Limit, stated in the record: /api/fix/analyse checks a fixed list of element
-- names. It does not report what a standard requires (for example the
-- customization identifier or the currency of an amount).
--
-- The conversion record of 0040 and the older, inactive record AmitTransform
-- (http://localhost:3000/api/convert) are left as they are. The new records
-- arrive as Published; an administrator verifies them in the application.

-- ----------------------------------------------------------------- preconditions

create temporary table _0047_api on commit drop as
select * from jsonb_populate_recordset(null::public.apis, $rows0047$[{"api_name":"AmitTransform Analyse Missing Invoice Fields API","official_api_name":"analyseMissingFields","description":"Reports which UBL elements the service finds in invoiceData and which it does not, by element name, and lists the field names /api/fix/apply accepts. It checks a fixed list of elements, not the rules of an invoice standard, and converts nothing.","api_endpoint":"https://invoice-conversion-api.onrender.com/api/fix/analyse","company_name":"AmitTransform","company_name_original":"AmitTransform (Amitabh K.)","official_company_name":"","documentation_url":"https://github.com/iamAmiK/invoice-conversion-api","source_url":"https://github.com/iamAmiK/invoice-conversion-api","http_method":"POST","category":"Transformation","communication_direction":"","authentication_method":"None","authentication_other":"","input_formats":["JSON"],"input_formats_original":["application/json"],"output_formats":["JSON"],"output_formats_original":["application/json"],"data_quality":"ok","access_scope":"public","review_status":"Published","id":"fa33b2f8-fa50-43f8-b849-ac4952479acb","website_url":"","authentication_details":"","network":""},{"api_name":"AmitTransform Apply Fixes and Convert to UBL XML API","official_api_name":"applyFixesAndConvert","description":"Writes the values in fixes into invoiceData, converts the result to UBL 2.1 XML with the flexible mapping, and returns the updated JSON, the XML and the field report. fixes is keyed by the names /api/fix/analyse lists in supportedFixFields (for example buyerReference); any other key is added at the top level when absent. Empty values are skipped.","api_endpoint":"https://invoice-conversion-api.onrender.com/api/fix/apply","company_name":"AmitTransform","company_name_original":"AmitTransform (Amitabh K.)","official_company_name":"","documentation_url":"https://github.com/iamAmiK/invoice-conversion-api","source_url":"https://github.com/iamAmiK/invoice-conversion-api","http_method":"POST","category":"Transformation","communication_direction":"","authentication_method":"None","authentication_other":"","input_formats":["JSON"],"input_formats_original":["application/json"],"output_formats":["JSON","XML"],"output_formats_original":["application/json"],"data_quality":"ok","access_scope":"public","review_status":"Published","id":"715d62e9-d24e-4ca9-819a-b89ff94df0e7","website_url":"","authentication_details":"","network":""}]$rows0047$::jsonb);

do $$
declare clash integer;
begin
  select count(*) into clash
    from _0047_api new_api
    join public.apis api
      on (lower(api.company_name) = lower(new_api.company_name) and lower(api.api_name) = lower(new_api.api_name))
      or (api.api_endpoint = new_api.api_endpoint and api.http_method = new_api.http_method);
  if clash <> 0 then
    raise exception '0047 precondition failed: an AmitTransform fix operation already exists.';
  end if;
end
$$;

