-- ------------------------------------------------------------------ postcondition

do $$
declare
  added integer;
  schema_rows integer;
  field_rows integer;
begin
  select count(*) into added from public.apis where id in (select id from _0047_api);
  select count(*) into schema_rows from public.api_schema where api_id in (select id from _0047_api);
  select count(*) into field_rows
    from public.api_schema_field f join public.api_schema s on s.id = f.schema_id
   where s.api_id in (select id from _0047_api);
  if added <> 2 or schema_rows <> 6 or field_rows <> 35 then
    raise exception '0047 postcondition failed: % APIs, % schemas, % fields.', added, schema_rows, field_rows;
  end if;
end
$$;
